package com.ventas.service;
import com.ventas.dto.RoleModels.*;import com.ventas.dto.UserAdminModels.Permission;import com.ventas.repository.RolePermissionRepository;import com.ventas.repository.RolePermissionRepository.Role;import com.ventas.repository.UserAdminRepository;import com.ventas.security.AuthModels.Identity;import com.ventas.security.AuthFailure;import com.fasterxml.jackson.databind.ObjectMapper;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import org.springframework.transaction.support.TransactionTemplate;
@Service @Profile("db") public class RolePermissionService{
 private final RolePermissionRepository repo;private final UserAdminRepository users;private final BusinessTransactions tx;private final TransactionTemplate transaction;private final ObjectMapper mapper;
 public RolePermissionService(RolePermissionRepository repo,UserAdminRepository users,BusinessTransactions tx,TransactionTemplate transaction,ObjectMapper mapper){this.repo=repo;this.users=users;this.tx=tx;this.transaction=transaction;this.mapper=mapper;}
 private static Set<String> codes(String s){return Set.copyOf(Arrays.asList(s.split(" ")));}
 static final Set<String> REQUIRED=Set.of("SEG.PERFIL","INI.VER");
 private static final Map<String,Set<String>> ALLOWED=Map.of(
 "VEN",codes("SEG.PERFIL INI.VER PRO.VER CLI.VER CLI.GESTIONAR INV.VER INV.ALERTAS VEN.VENDER VEN.DESCUENTO VEN.HISTORIAL VEN.REIMPRIMIR VEN.DEVOLVER VEN.COPIAR VEN.XML VEN.MEDIDAS COC.COTIZAR CRE.VER CRE.ABONAR CAJ.OPERAR CAJ.HISTORIAL DES.VER DES.GESTIONAR"),
 "ALM",codes("SEG.PERFIL INI.VER PRO.VER PRO.GESTIONAR PRO.PRESENTACIONES PRO.MEDIDAS CAT.GESTIONAR UNI.GESTIONAR PRV.GESTIONAR COM.OC COM.INGRESO INV.VER INV.ALERTAS INV.AJUSTAR INV.TOMA_GESTIONAR INV.TOMA_CONTAR INV.TRANSFORMAR DES.VER DES.GESTIONAR REP.INVENTARIO REP.EXPORTAR"),
 "AYU",codes("SEG.PERFIL INI.VER PRO.VER INV.VER INV.ALERTAS INV.TOMA_CONTAR DES.VER DES.GESTIONAR"));
 private void access(Identity a){if(a==null||!"ADM".equals(a.rol())||a.cambioClaveObligatorio()||!a.permisos().contains("SEG.PERMISOS"))throw new AuthFailure(403,"Solo administración puede gestionar permisos");}
 private String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException("No se pudo preparar el registro de permisos");}}
 String version(Role r,List<Permission> catalog,List<String> assigned){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json(List.of(r,catalog,new TreeSet<>(assigned))).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException("No se pudo verificar la versión del rol");}}
 private Editor read(long id,boolean lock){var role=repo.role(id,lock).orElseThrow(()->new AuthFailure(404,"Rol no encontrado"));var all=repo.catalog();var assigned=repo.assigned(id);boolean editable=ALLOWED.containsKey(role.code())&&role.state().equals("A");var allowed=ALLOWED.getOrDefault(role.code(),Set.of());var available=all.stream().filter(p->role.code().equals("ADM")||allowed.contains(p.codigo())||assigned.contains(p.codigo())).map(p->p.codigo().equals("VEN.XML")?new Permission(p.codigo(),p.modulo(),p.descripcion()+" (pendiente de integración)"):p).toList();return new Editor(id,role.code(),role.name(),role.description(),role.state(),editable,version(role,all,assigned),available,assigned,new ArrayList<>(new TreeSet<>(REQUIRED)),repo.users(id));}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Editor get(Identity a,long id){access(a);return read(id,false);}
 void validate(Editor current,Change input){if(!current.editable())throw new AuthFailure(409,"El rol administrador y los perfiles inactivos están protegidos");if(input.version()==null||!input.version().equals(current.version()))throw new AuthFailure(409,"Los permisos cambiaron. Recarga el rol antes de guardar");if(input.permisos()==null||input.permisos().size()>100||new HashSet<>(input.permisos()).size()!=input.permisos().size())throw new AuthFailure(400,"Revisa la lista de permisos");var requested=new HashSet<>(input.permisos());if(requested.contains("VEN.XML")!=current.asignados().contains("VEN.XML"))throw new AuthFailure(400,"El permiso XML se conserva hasta completar su integración");var allowed=ALLOWED.get(current.codigo());var available=current.disponibles().stream().map(Permission::codigo).collect(java.util.stream.Collectors.toSet());if(!requested.containsAll(REQUIRED))throw new AuthFailure(400,"El perfil requiere acceso al inicio y cambio de contraseña propia");var invalid=new TreeSet<>(requested);invalid.removeAll(allowed);if(!invalid.isEmpty())throw new AuthFailure(400,"Permisos incompatibles con este perfil: "+String.join(", ",invalid));if(!available.containsAll(requested))throw new AuthFailure(400,"Solo se admiten los permisos disponibles y activos");
 for(var d:Map.of("VEN.VENDER",Set.of("PRO.VER","CAJ.OPERAR"),"VEN.COPIAR",Set.of("VEN.HISTORIAL","VEN.VENDER"),"CRE.ABONAR",Set.of("CRE.VER","CAJ.OPERAR"),"DES.GESTIONAR",Set.of("DES.VER"),"INV.TOMA_CONTAR",Set.of("INV.VER"),"REP.EXPORTAR",Set.of("REP.INVENTARIO"),"COC.COTIZAR",Set.of("PRO.VER")).entrySet())if(requested.contains(d.getKey())&&!requested.containsAll(d.getValue()))throw new AuthFailure(400,"La acción "+label(current,d.getKey())+" requiere: "+String.join(", ",new TreeSet<>(d.getValue()).stream().map(code->label(current,code)).toList()));}
 private String label(Editor editor,String code){return editor.disponibles().stream().filter(p->p.codigo().equals(code)).map(Permission::descripcion).findFirst().orElse(code);}
 public Result save(Identity a,String pc,long id,Change input){access(a);return transaction.execute(status->{users.serialize();return tx.write(a,pc,"SEG.PERMISOS",()->{if(!users.user(a.id(),true).orElseThrow(AuthFailure::expired).rol().equals("ADM"))throw new AuthFailure(403,"Solo administración puede gestionar permisos");var before=read(id,true);validate(before,input);var next=new TreeSet<>(input.permisos());if(next.equals(new TreeSet<>(before.asignados())))return new Result(before,0);repo.lockUsers(id);repo.assignments(id,next);long revoked=repo.revoke(id);var after=read(id,false);repo.audit(a.id(),id,json(Map.of("rol",before.codigo(),"permisos",before.asignados())),json(Map.of("rol",after.codigo(),"permisos",after.asignados(),"sesionesCerradas",revoked)));return new Result(after,revoked);});});}
}
